export function getCommandDef(code: string): CommandDef | undefined {
	return COMMAND_REGISTRY[code];
}

export function getCommandsByType(type: CommandActionType): CommandDef[] {
	return Object.values(COMMAND_REGISTRY).filter((cmd) => cmd.actionType === type);
}

export function getValueName(code: string, param: string): string | undefined {
	const cmd = COMMAND_REGISTRY[code];
	if (!cmd) return undefined;
	const value = cmd.values.find((v) => v.param.toLowerCase() === param.toLowerCase());
	return value?.name;
}
